using EmployeeLeaveManagementSystem.Data;
using EmployeeLeaveManagementSystem.Models;
using EmployeeLeaveManagementSystem.ViewModels;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace EmployeeLeaveManagementSystem.Controllers;

[Authorize]
public class LeaveRequestsController : Controller
{
    private readonly ApplicationDbContext _db; private readonly UserManager<ApplicationUser> _users;
    public LeaveRequestsController(ApplicationDbContext db, UserManager<ApplicationUser> users) { _db = db; _users = users; }
    private async Task<Employee?> CurrentEmployeeAsync() { var uid = _users.GetUserId(User); var user = await _users.GetUserAsync(User); return await _db.Employees.FirstOrDefaultAsync(e => e.UserId == uid || e.Email == user!.Email); }
    public async Task<IActionResult> Index(LeaveStatus? status) { var q = _db.LeaveRequests.Include(l => l.Employee).AsQueryable(); if (!User.IsInRole("Admin")) { var emp = await CurrentEmployeeAsync(); if (emp is null) return RedirectToAction("Index", "Dashboard"); q = q.Where(l => l.EmployeeId == emp.Id); } if (status.HasValue) q = q.Where(l => l.Status == status); ViewBag.Status = status; return View(await q.OrderByDescending(l => l.AppliedOn).ToListAsync()); }
    [Authorize(Roles = "Employee,Admin")] public IActionResult Apply() => View(new LeaveApplyViewModel());
    [HttpPost, Authorize(Roles = "Employee,Admin"), ValidateAntiForgeryToken] public async Task<IActionResult> Apply(LeaveApplyViewModel model) { if (model.StartDate.Date < DateTime.Today) ModelState.AddModelError(nameof(model.StartDate), "Start date cannot be in the past."); if (model.EndDate.Date < model.StartDate.Date) ModelState.AddModelError(nameof(model.EndDate), "End date must be on or after the start date."); var emp = await CurrentEmployeeAsync(); if (emp is null) ModelState.AddModelError(string.Empty, "Your account is not linked to an employee profile. Ask an administrator to create/link your profile."); if (ModelState.IsValid && emp is not null) { var overlap = await _db.LeaveRequests.AnyAsync(l => l.EmployeeId == emp.Id && l.Status == LeaveStatus.Approved && model.StartDate <= l.EndDate && model.EndDate >= l.StartDate); if (overlap) ModelState.AddModelError(string.Empty, "These dates overlap with an approved leave."); } if (!ModelState.IsValid) return View(model); _db.LeaveRequests.Add(new LeaveRequest { EmployeeId = emp!.Id, LeaveType = model.LeaveType, StartDate = model.StartDate.Date, EndDate = model.EndDate.Date, Reason = model.Reason.Trim(), AppliedOn = DateTime.UtcNow, Status = LeaveStatus.Pending }); await _db.SaveChangesAsync(); TempData["Success"] = "Leave request submitted."; return RedirectToAction(nameof(Index)); }
    [Authorize(Roles = "Admin")] public async Task<IActionResult> Review(int id) { var leave = await _db.LeaveRequests.Include(l => l.Employee).FirstOrDefaultAsync(l => l.Id == id); return leave is null ? NotFound() : View(leave); }
    [HttpPost, Authorize(Roles = "Admin"), ValidateAntiForgeryToken] public async Task<IActionResult> Decide(LeaveDecisionViewModel model, string decision) { var leave = await _db.LeaveRequests.FindAsync(model.Id); if (leave is null) return NotFound(); if (leave.Status != LeaveStatus.Pending) { TempData["Error"] = "Only pending requests can be reviewed."; return RedirectToAction(nameof(Index)); } if (decision != "approve" && decision != "reject") return BadRequest(); if (decision == "approve") { var overlap = await _db.LeaveRequests.AnyAsync(l => l.Id != leave.Id && l.EmployeeId == leave.EmployeeId && l.Status == LeaveStatus.Approved && leave.StartDate <= l.EndDate && leave.EndDate >= l.StartDate); if (overlap) { TempData["Error"] = "This request overlaps another approved leave."; return RedirectToAction(nameof(Index)); } } leave.Status = decision == "approve" ? LeaveStatus.Approved : LeaveStatus.Rejected; leave.AdminComment = model.AdminComment; await _db.SaveChangesAsync(); TempData["Success"] = $"Leave request {leave.Status.ToString().ToLowerInvariant()}."; return RedirectToAction(nameof(Index)); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> Cancel(int id) { var leave = await _db.LeaveRequests.FindAsync(id); if (leave is null) return NotFound(); if (!User.IsInRole("Admin")) { var emp = await CurrentEmployeeAsync(); if (emp is null || leave.EmployeeId != emp.Id) return Forbid(); } if (leave.Status != LeaveStatus.Pending) { TempData["Error"] = "Only pending requests can be cancelled."; return RedirectToAction(nameof(Index)); } leave.Status = LeaveStatus.Cancelled; await _db.SaveChangesAsync(); TempData["Success"] = "Leave request cancelled."; return RedirectToAction(nameof(Index)); }
}
